contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint v, uint v2) public {
        // Before initialization, SetMinSum(v) must succeed and take effect.
        c.SetMinSum(v);
        uint msAfter = c.MinSum();

        // Initialize the contract.
        c.Initialized();

        // After initialization, SetMinSum must revert.
        bool reverted;
        try c.SetMinSum(v2) { reverted = false; } catch { reverted = true; }

        uint msFinal = c.MinSum();
        assert(reverted && msAfter == v && msFinal == msAfter);
    }
}

