contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, uint minSum) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(minSum);
        c.Deposit{value: amount}();
        uint balBefore = c.balances(address(this));
        uint ethBefore = address(c).balance;
        c.Collect(amount);
        assert(
            amount >= minSum &&
            c.balances(address(this)) == 0 &&
            address(c).balance == ethBefore - amount &&
            balBefore == amount
